# Let's search all matches from the script above
import concurrent.futures, requests

r = requests.get('https://pubchem.ncbi.nlm.nih.gov/classification_2/classification_2.fcgi?format=json')
hierarchies = r.json()['Hierarchies']['Hierarchy']

results = []
def check_hid(h):
    hid = h['HID']
    sname = h.get('SourceName', '')
    try:
        res = requests.get(f'https://pubchem.ncbi.nlm.nih.gov/classification_2/classification_2.fcgi?hid={hid}&format=json', timeout=10)
        if res.status_code == 200:
            nodes = res.json()['Hierarchies']['Hierarchy'][0].get('Node', [])
            for node in nodes:
                name = str(node.get('Information', {}).get('Name', ''))
                if any(k in name.lower() for k in ['food additive', 'ncats', 'status']):
                    results.append((hid, sname, node.get('NodeID'), name))
    except Exception as e:
        pass

with concurrent.futures.ThreadPoolExecutor(max_workers=10) as executor:
    executor.map(check_hid, hierarchies)

for res in results:
    if 'food' in res[3].lower() or 'additive' in res[3].lower() or 'ncats' in res[3].lower():
        print(res)
